// @generated by:gauntlet run:godseye-local-delivery
import { randomUUID } from "node:crypto";
import { InfrastructureEngine } from "@godseye/core";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { deliveryCommitments } from "../packages/core/src/delivery-capacity.js";
import { type DeliveryFixture, deliveryFixture } from "./delivery-helpers.js";

describe("durable delivery receipts, reconstruction and late effects", () => {
  let fixture: DeliveryFixture;
  beforeEach(async () => {
    fixture = await deliveryFixture();
  });
  afterEach(async () => {
    await fixture.store.close();
  });
  const view = () => fixture.infrastructure.delivery.overview(fixture.freshOwner());
  async function replacement() {
    const policy = await fixture.createPolicy(),
      first = await fixture.push(),
      a = await fixture.build(policy.id, first.id),
      active = await fixture.release(policy.id, first.id, a.artifact.id);
    fixture.source.head = "b".repeat(40);
    const next = await fixture.push(),
      b = await fixture.build(policy.id, next.id),
      preparation = await fixture.prepare({
        policyId: policy.id,
        ciRunId: next.id,
        intent: "release",
        artifactId: b.artifact.id,
      }),
      run = await fixture.admit(preparation);
    return { policy, a, active, b, preparation, run };
  }
  it("T-AC-50 reconciles a lost build receipt after controller reconstruction without repeating the build", async () => {
    const policy = await fixture.createPolicy(),
      ci = await fixture.push(),
      preparation = await fixture.prepare({ policyId: policy.id, ciRunId: ci.id, intent: "build" }),
      run = await fixture.admit(preparation);
    fixture.provider.lostAcknowledgments.add("build");
    await fixture.infrastructure.foundation.tick("lost-build-receipt-worker");
    expect((await view()).deployments.find((item) => item.id === run.id)?.state).toBe("unknown");
    const effects = structuredClone(fixture.provider.effects),
      restarted = new InfrastructureEngine(fixture.store, fixture.configuration);
    await restarted.foundation.reconcile(fixture.freshOwner(), run.runId, randomUUID());
    expect(
      (await restarted.delivery.overview(fixture.freshOwner())).deployments.find(
        (item) => item.id === run.id,
      )?.state,
    ).toBe("built");
    expect((await restarted.delivery.overview(fixture.freshOwner())).artifacts).toHaveLength(1);
    expect(fixture.provider.effects).toEqual(effects);
  });
  it("T-AC-50 reconciles a lost traffic-switch receipt and retires only the independently absent previous runtime", async () => {
    const subject = await replacement();
    fixture.provider.lostAcknowledgments.add("promote");
    await fixture.infrastructure.foundation.tick("lost-promotion-receipt-worker");
    expect((await view()).deployments.find((item) => item.id === subject.run.id)?.state).toBe(
      "unknown",
    );
    expect(fixture.provider.active.get(fixture.development.id)).toBe(subject.b.artifact.digest);
    const effects = structuredClone(fixture.provider.effects),
      restarted = new InfrastructureEngine(fixture.store, fixture.configuration);
    await restarted.foundation.reconcile(fixture.freshOwner(), subject.run.runId, randomUUID());
    const current = await restarted.delivery.overview(fixture.freshOwner());
    expect(current.deployments.find((item) => item.id === subject.run.id)?.state).toBe("active");
    expect(current.deployments.find((item) => item.id === subject.active.run.id)?.state).toBe(
      "retired",
    );
    expect(current.artifacts).toHaveLength(2);
    expect(fixture.provider.effects).toEqual(effects);
  });
  it.each(["cancel", "policy", "head", "epoch", "provider-generation"])(
    "T-AC-47 T-AC-50 fences %s after a staged side effect while retaining target capacity and previous traffic",
    async (mode) => {
      const subject = await replacement();
      fixture.provider.afterAction = async (action) => {
        if (action !== "stage") return;
        if (mode === "cancel")
          await fixture.infrastructure.foundation.cancel(
            fixture.freshOwner(),
            subject.run.runId,
            randomUUID(),
          );
        if (mode === "policy")
          await fixture.infrastructure.delivery.revokePolicy(
            fixture.freshOwner(),
            subject.policy.id,
            subject.policy.revision,
            randomUUID(),
          );
        if (mode === "head") fixture.source.head = "c".repeat(40);
        if (mode === "epoch")
          await fixture.infrastructure.foundation.advanceEpoch(
            fixture.freshOwner(),
            fixture.development.id,
            randomUUID(),
          );
        if (mode === "provider-generation") fixture.provider.binding.generation += 1;
      };
      await fixture.infrastructure.foundation.tick("staged-authority-loss-worker");
      expect((await view()).deployments.find((item) => item.id === subject.run.id)?.state).toBe(
        "unknown",
      );
      expect(fixture.provider.active.get(fixture.development.id)).toBe(subject.a.artifact.digest);
      expect(fixture.provider.effects.filter((effect) => effect.action === "promote")).toHaveLength(
        1,
      );
      expect(
        (await deliveryCommitments(fixture.store.db)).filter((item) => item.cpuMilliCores > 0),
      ).toHaveLength(2);
      expect(await fixture.infrastructure.foundation.tick("never-repeat-staged-worker")).toBe(
        false,
      );
    },
  );
  it("T-AC-50 preserves late materialized traffic as unknown after cancellation instead of claiming the switch was undone", async () => {
    const subject = await replacement();
    fixture.provider.afterAction = async (action) => {
      if (action === "promote")
        await fixture.infrastructure.foundation.cancel(
          fixture.freshOwner(),
          subject.run.runId,
          randomUUID(),
        );
    };
    await fixture.infrastructure.foundation.tick("late-physical-traffic-worker");
    expect((await view()).deployments.find((item) => item.id === subject.run.id)?.state).toBe(
      "unknown",
    );
    expect(fixture.provider.active.get(fixture.development.id)).toBe(subject.b.artifact.digest);
    expect(
      (await deliveryCommitments(fixture.store.db)).filter((item) => item.cpuMilliCores > 0),
    ).toHaveLength(2);
    expect(await fixture.infrastructure.foundation.tick("no-duplicate-late-switch-worker")).toBe(
      false,
    );
  });
  it("T-AC-47 rechecks policy inside terminal Foundation settlement after runtime evidence was recorded", async () => {
    const subject = await replacement(),
      finish = fixture.infrastructure.foundation.finish.bind(fixture.infrastructure.foundation);
    fixture.infrastructure.foundation.finish = async (context, outcome) => {
      if (context.runId === subject.run.runId)
        await fixture.infrastructure.delivery.revokePolicy(
          fixture.freshOwner(),
          subject.policy.id,
          subject.policy.revision,
          randomUUID(),
        );
      return finish(context, outcome);
    };
    await fixture.infrastructure.foundation.tick("terminal-policy-race-worker");
    expect((await view()).deployments.find((item) => item.id === subject.run.id)?.state).toBe(
      "unknown",
    );
    expect(fixture.provider.active.get(fixture.development.id)).toBe(subject.b.artifact.digest);
    expect(
      (await deliveryCommitments(fixture.store.db)).filter((item) => item.cpuMilliCores > 0),
    ).toHaveLength(2);
    const [target] = await fixture.store.db
      .select()
      .from(schema.deliveryTargets)
      .where(eq(schema.deliveryTargets.environmentId, fixture.development.id));
    expect(target?.pendingRunId).toBe(subject.run.runId);
  });
  it("T-AC-47 releases a definitively undispatched stale build lane so the new accepted head can build", async () => {
    const policy = await fixture.createPolicy(),
      old = await fixture.push(),
      preparation = await fixture.prepare({
        policyId: policy.id,
        ciRunId: old.id,
        intent: "build",
      }),
      run = await fixture.admit(preparation);
    fixture.source.head = "b".repeat(40);
    await fixture.infrastructure.foundation.tick("stale-before-intention-worker");
    expect((await view()).deployments.find((item) => item.id === run.id)?.state).toBe("released");
    const current = await fixture.push(),
      built = await fixture.build(policy.id, current.id);
    expect(built.artifact.commitSha).toBe(fixture.source.head);
    expect(fixture.provider.effects.filter((effect) => effect.action === "build")).toHaveLength(1);
  });
  it("T-AC-50 never adopts a foreign observed runtime or releases uncertain reservations from a copied digest", async () => {
    const subject = await replacement();
    fixture.provider.inspectionResult = (evidence) => ({
      ...evidence,
      scope: { ...evidence.scope, environmentId: fixture.production.id },
    });
    await fixture.infrastructure.foundation.tick("foreign-inspection-worker");
    expect((await view()).deployments.find((item) => item.id === subject.run.id)?.state).toBe(
      "unknown",
    );
    const [target] = await fixture.store.db
      .select()
      .from(schema.deliveryTargets)
      .where(eq(schema.deliveryTargets.environmentId, fixture.development.id));
    expect(target?.pendingRunId).toBe(subject.run.runId);
    expect(fixture.provider.active.has(fixture.production.id)).toBe(false);
  });
});
